-- Exact failed pre-handoff recovery and one owner-reviewed setup repair.
-- Generated by official Supabase CLI 2.120.0. No live authority is installed.
-- Remote terminal proof is deliberately different from local observer disposal.
begin;
create table private.r12_steel_setup_recovery_observations(
 observation_hash text primary key check(observation_hash=private.stage14_hash(content)),
 operation_id uuid not null references private.r12_etsy_steel_setups(operation_id),content jsonb not null,created_at timestamptz not null default clock_timestamp());
create table private.r12_steel_setup_recoveries(
 operation_id uuid primary key references private.r12_etsy_steel_setups(operation_id),
 recovery_hash text not null unique check(recovery_hash=private.stage14_hash(content-'recoveryHash')),
 failed_receipt_hash text not null references private.r12_etsy_steel_receipts(receipt_hash),
 release_evidence_hash text not null references private.r12_direct_browser_evidence(evidence_hash),
 content jsonb not null,created_at timestamptz not null default clock_timestamp());
create table private.r12_steel_setup_replacement_proposals(
 id uuid primary key,operation_id uuid not null references private.r12_etsy_steel_setups(operation_id),
 envelope_id uuid not null references private.r12_direct_test_envelopes(id),owner_id uuid not null references auth.users(id),
 submission_id uuid not null,request_hash text not null,replacement_operation_id uuid not null,
 content jsonb not null,proposal_hash text not null unique check(proposal_hash=private.stage14_hash(content-'proposalHash')),
 expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),unique(owner_id,submission_id));
create table private.r12_steel_setup_repair_debits(
 envelope_id uuid primary key references private.r12_direct_test_envelopes(id),
 proposal_id uuid not null unique references private.r12_steel_setup_replacement_proposals(id),
 original_operation_id uuid not null unique references private.r12_etsy_steel_setups(operation_id),replacement_operation_id uuid not null unique,
 owner_id uuid not null references auth.users(id),content jsonb not null,
 debit_hash text not null unique check(debit_hash=private.stage14_hash(content-'debitHash')),created_at timestamptz not null default clock_timestamp());
do $$ declare t text;begin foreach t in array array['r12_steel_setup_recovery_observations','r12_steel_setup_recoveries','r12_steel_setup_replacement_proposals','r12_steel_setup_repair_debits'] loop
 execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);
 execute format('create trigger immutable_setup_recovery before insert or update or delete on private.%I for each row execute function private.r05_guard()',t);end loop;end $$;

create function private.r12_steel_setup_recovery_key_revoke_lock() returns trigger language plpgsql set search_path='' as $$
begin perform 1 from public.businesses b join private.r12_direct_test_envelopes e on e.business_id=b.id join private.r12_direct_browser_evidence_keys k on k.envelope_id=e.id where k.key_hash=new.key_hash for update of b;return new;end $$;
create trigger r12_steel_setup_recovery_revoke_lock before insert on private.r12_direct_browser_evidence_key_revocations for each row execute function private.r12_steel_setup_recovery_key_revoke_lock();

create function private.r12_steel_setup_recovery_context(operation uuid,failed_hash text) returns jsonb language plpgsql set search_path='' as $$
declare s private.r12_etsy_steel_setups;e private.r12_direct_test_envelopes;o private.r12_direct_browser_operations;r private.r12_direct_browser_routes;f private.r12_etsy_steel_receipts;u private.r12_steel_create_config_uses;body jsonb;qualification jsonb;begin
 select * into strict s from private.r12_etsy_steel_setups where operation_id=operation;
 select * into strict e from private.r12_direct_test_envelopes where id=s.envelope_id;
 perform 1 from public.businesses where id=s.business_id and owner_user_id=s.owner_id for update;if not found then raise exception 'r12_setup_recovery_owner_changed';end if;
 select * into strict o from private.r12_direct_browser_operations where id=s.operation_id and request_id=s.request_id and envelope_id=s.envelope_id;
 select * into strict r from private.r12_direct_browser_routes where route_hash=s.route_hash;
 select * into f from private.r12_etsy_steel_receipts where receipt_hash=failed_hash and operation_id=s.operation_id;
 select * into u from private.r12_steel_create_config_uses where operation_id=s.operation_id;
 if f.receipt_hash is null or f.receipt->>'scopeHash' is distinct from s.scope_hash or coalesce(f.receipt->>'status','') not in ('failed','stopped')
 or f.receipt->'handoffId' is distinct from 'null'::jsonb or f.receipt->'profileBindingId' is distinct from 'null'::jsonb
 or f.receipt->>'receiptHash' is distinct from private.stage14_hash(f.receipt-'receiptHash')
 or not exists(select 1 from private.r12_etsy_steel_stops where operation_id=s.operation_id and owner_id=s.owner_id)
 or not exists(select 1 from private.r12_etsy_steel_dispatches where operation_id=s.operation_id)
 or not exists(select 1 from private.r05_markers where request_id=s.request_id)
 or u.operation_id is null or exists(select 1 from private.r12_etsy_steel_handoffs where operation_id=s.operation_id)
 or exists(select 1 from private.r12_etsy_steel_admissions where operation_id=s.operation_id and stage<>'create')
 or exists(select 1 from private.r12_etsy_steel_candidates where operation_id=s.operation_id)
 or exists(select 1 from private.r12_etsy_steel_verification_runs where setup_operation_id=s.operation_id)
 or exists(select 1 from private.r12_etsy_steel_receipts where operation_id=s.operation_id and receipt->>'status' in ('awaiting_owner','profile_pending_verification'))
 then raise exception 'r12_setup_recovery_no_handoff_required';end if;
 qualification:=jsonb_build_object('providerProjectId',r.provider_project_id,'providerAccountHash',r.provider_account_hash,'routeHash',r.route_hash,'tariffHash',r.tariff_hash,'qualificationHash',r.qualification_hash,'maximumSessionMs',r.maximum_session_ms,'maximumSessionMicrounits',r.maximum_session_microunits::text,'settlementContractHash',r.settlement_contract_hash,'priceEvidenceHash',r.content->'priceEvidenceHash','retentionDisclosure',r.content->'retentionDisclosure','validFrom',private.r12_direct_time(r.valid_from),'validUntil',private.r12_direct_time(r.valid_until),'revoked',exists(select 1 from private.r12_direct_browser_route_revocations where route_hash=r.route_hash),'usageBound',r.content->'usageBound');
 body:=jsonb_build_object('version','etsy.steel-recovery-context.1','businessId',s.business_id,'operationId',s.operation_id,'scopeHash',s.scope_hash,'testEnvelopeId',e.id,'testEnvelopeHash',e.content_hash,'providerProjectId',r.provider_project_id,'routeHash',r.route_hash,'requestedTimeoutMs',s.scope->'maximumSessionMs','maximumBrowserMicrounits',o.maximum_microunits::text,'failedReceiptHash',f.receipt_hash,'configurationAdmissionHash',u.admission_hash,'qualification',qualification);
 return body||jsonb_build_object('contextHash',private.stage14_hash(body));
end $$;
create function private.r12_steel_setup_recovery_receipt(operation uuid,failed_hash text) returns jsonb language plpgsql stable set search_path='' as $$
declare s private.r12_etsy_steel_setups;o private.r12_direct_browser_operations;p private.r12_steel_setup_recoveries;a private.r12_direct_browser_accounting;ok boolean;begin
 select * into strict s from private.r12_etsy_steel_setups where operation_id=operation;select * into strict o from private.r12_direct_browser_operations where id=operation;
 select * into p from private.r12_steel_setup_recoveries where operation_id=operation;
 select * into a from private.r12_direct_browser_accounting where operation_id=operation order by revision desc limit 1;
 ok:=p.operation_id is not null and a.operation_id is not null and not exists(select 1 from private.r12_direct_browser_anomalies where operation_id=operation)
 and not exists(select 1 from private.r12_direct_browser_route_revocations where route_hash=o.route_hash);
 return jsonb_build_object('version','etsy.steel-recovery-receipt.1','operationId',operation,'recoveryHash',case when ok then p.recovery_hash else null end,'failedReceiptHash',failed_hash,'accountingRecordHash',case when ok then a.record_hash else null end,'status',case when ok then a.status else 'unknown' end,'heldMaximumMicrounits',o.maximum_microunits::text,'testExposure',private.r12_direct_test_exposure(s.envelope_id));
end $$;
create function public.r12_etsy_steel_recovery_server(p_business_id uuid,p_operation text,p_payload jsonb,p_server_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare s private.r12_etsy_steel_setups;e private.r12_direct_test_envelopes;o private.r12_direct_browser_operations;r private.r12_direct_browser_routes;k private.r12_direct_browser_evidence_keys;
 ctx jsonb;usage jsonb;f jsonb;session jsonb;identity_hash text;observation jsonb;observed_hash text;rel jsonb;rel_hash text;us jsonb;us_hash text;proof jsonb;body jsonb;last private.r12_direct_browser_accounting;field text;valid boolean;begin
 if p_server_key is null or length(p_server_key) not between 32 and 200 then raise exception 'r12_setup_recovery_evidence_key_required' using errcode='42501';end if;
 perform private.r04_keys(p_payload,case when p_operation='inputs' then array['operationId','failedReceiptHash'] else array['operationId','failedReceiptHash','usage'] end);perform private.r04_safe(p_payload);
 select * into s from private.r12_etsy_steel_setups where operation_id=(p_payload->>'operationId')::uuid and business_id=p_business_id;
 select * into k from private.r12_direct_browser_evidence_keys where key_hash=encode(extensions.digest(p_server_key,'sha256'),'hex') and envelope_id=s.envelope_id and route_hash=s.route_hash;
 perform 1 from public.businesses where id=p_business_id for update;
 if s.operation_id is null or k.key_hash is null or k.valid_until<=clock_timestamp() or exists(select 1 from private.r12_direct_browser_evidence_key_revocations where key_hash=k.key_hash) then raise exception 'r12_setup_recovery_evidence_key_required' using errcode='42501';end if;
 ctx:=private.r12_steel_setup_recovery_context(s.operation_id,p_payload->>'failedReceiptHash');if p_operation='inputs' then return ctx;end if;
 if p_operation is distinct from 'record' then raise exception 'r12_setup_recovery_operation';end if;
 usage:=p_payload->'usage';perform private.r04_keys(usage,array['version','sessionId','providerProjectId','providerStatus','providerTimeoutMs','durationMs','proxyBytesUsed','proxySource','solveCaptcha']);
 if usage->>'version' is distinct from 'etsy.steel-terminal-usage.1' or usage->>'sessionId' is distinct from s.operation_id::text or usage->>'providerProjectId' is distinct from ctx->>'providerProjectId' or coalesce(usage->>'providerStatus','') not in ('released','failed') then raise exception 'r12_setup_recovery_terminal_usage_required';end if;
 foreach field in array array['providerTimeoutMs','durationMs','proxyBytesUsed'] loop
 if usage->field is distinct from 'null'::jsonb and (jsonb_typeof(usage->field) is distinct from 'number' or coalesce(usage->>field,'')!~'^(0|[1-9][0-9]{0,8})$') then raise exception 'r12_setup_recovery_usage_invalid';end if;end loop;
 if usage->'solveCaptcha' not in ('true'::jsonb,'false'::jsonb,'null'::jsonb) or (usage->'proxySource' is distinct from 'null'::jsonb and coalesce(usage->>'proxySource','') not in ('steel','external','unknown')) then raise exception 'r12_setup_recovery_usage_invalid';end if;
 select * into strict e from private.r12_direct_test_envelopes where id=s.envelope_id;select * into strict o from private.r12_direct_browser_operations where id=s.operation_id;select * into strict r from private.r12_direct_browser_routes where route_hash=s.route_hash;
 observation:=jsonb_build_object('operationId',s.operation_id,'failedReceiptHash',p_payload->>'failedReceiptHash','usage',usage);observed_hash:=private.stage14_hash(observation);
 insert into private.r12_steel_setup_recovery_observations values(observed_hash,s.operation_id,observation,clock_timestamp()) on conflict(observation_hash) do nothing;
 session:=jsonb_build_object('sessionId',s.operation_id,'providerProjectId',r.provider_project_id,'providerAccountHash',r.provider_account_hash);
 identity_hash:=private.stage14_hash(jsonb_build_object('provider','steel','providerProjectId',r.provider_project_id,'providerAccountHash',r.provider_account_hash,'sessionId',s.operation_id));
 if exists(select 1 from private.r12_direct_browser_sessions where operation_id=s.operation_id and content is distinct from session) then raise exception 'r12_setup_recovery_session_conflict';end if;
 insert into private.r12_direct_browser_sessions values(s.operation_id,s.operation_id::text,r.provider_project_id,identity_hash,session,private.stage14_hash(session),clock_timestamp()) on conflict(operation_id) do nothing;
 -- A positive violation is durable even if an earlier observation was bounded.
 if coalesce((usage->>'durationMs')::bigint>(ctx->>'requestedTimeoutMs')::bigint,false) or coalesce((usage->>'proxyBytesUsed')::bigint>0,false) or usage->'solveCaptcha'='true'::jsonb or usage->>'proxySource' in ('steel','external') then
 perform private.r12_direct_browser_anomaly(s.operation_id,'unbounded_usage',observed_hash);return private.r12_steel_setup_recovery_receipt(s.operation_id,p_payload->>'failedReceiptHash');end if;
 valid:=r.content->'usageBound'='{"version":"r12.steel-usage-bound.1","maximumProxyBytes":0,"tariffCoversSessionAndProfileLifecycle":true,"captchaDisabled":true,"extraServicesDisabled":true}'::jsonb
 and usage->>'providerTimeoutMs'=ctx->>'requestedTimeoutMs' and (usage->>'durationMs')::bigint<=(ctx->>'requestedTimeoutMs')::bigint
 and usage->'proxyBytesUsed'='0'::jsonb and usage->'proxySource'='null'::jsonb and usage->'solveCaptcha'='false'::jsonb
 and r.maximum_session_microunits<=o.maximum_microunits and (ctx->>'requestedTimeoutMs')::integer between 15000 and r.maximum_session_ms
 and not exists(select 1 from private.r12_direct_browser_route_revocations where route_hash=r.route_hash)
 and not exists(select 1 from private.r12_direct_browser_anomalies where operation_id=s.operation_id);
 if valid is distinct from true then return private.r12_steel_setup_recovery_receipt(s.operation_id,p_payload->>'failedReceiptHash');end if;
 if exists(select 1 from private.r12_steel_setup_recoveries where operation_id=s.operation_id) then return private.r12_steel_setup_recovery_receipt(s.operation_id,p_payload->>'failedReceiptHash');end if;
 select receipt into strict f from private.r12_etsy_steel_receipts where receipt_hash=p_payload->>'failedReceiptHash' and operation_id=s.operation_id;
 if exists(select 1 from private.r12_direct_browser_receipts where operation_id=s.operation_id and content is distinct from f) then raise exception 'r12_setup_recovery_receipt_conflict';end if;
 insert into private.r12_direct_browser_receipts values(s.operation_id,f->>'receiptHash',f,clock_timestamp()) on conflict(operation_id) do nothing;
 rel:=jsonb_build_object('version','etsy.steel-provider-terminal-no-handoff.1','operationId',s.operation_id,'sessionId',s.operation_id,'providerProjectId',r.provider_project_id,'scopeHash',s.scope_hash,'testEnvelopeId',e.id,'testEnvelopeHash',e.content_hash,'failedReceiptHash',f->>'receiptHash','configurationAdmissionHash',ctx->>'configurationAdmissionHash','terminal',true,'providerStatus',usage->>'providerStatus','providerReadbackHash',private.stage14_hash(usage),'ownerHandoffIssued',false,'localObserverDisposal','unattested');rel_hash:=private.stage14_hash(rel);
 insert into private.r12_direct_browser_evidence values(rel_hash,s.operation_id,'release','steel-no-handoff:'||s.operation_id::text,s.operation_id::text,r.provider_project_id,rel,clock_timestamp());
 us:=jsonb_build_object('operationId',s.operation_id,'sessionId',s.operation_id,'providerProjectId',r.provider_project_id,'usageIdentityHash',identity_hash,'tariffHash',r.tariff_hash,'qualificationHash',r.qualification_hash,'withinQualifiedLimits',true,'maximumMicrounits',r.maximum_session_microunits::text,'requestedTimeoutMs',ctx->'requestedTimeoutMs','providerTimeoutMs',usage->'providerTimeoutMs','durationMs',usage->'durationMs','proxyBytesUsed',usage->'proxyBytesUsed','proxySource',usage->'proxySource','solveCaptcha',usage->'solveCaptcha','extraServicesDisabled',true,'providerReadbackHash',private.stage14_hash(usage));us_hash:=private.stage14_hash(us);
 insert into private.r12_direct_browser_evidence values(us_hash,s.operation_id,'usage_bound','steel-no-handoff-usage:'||s.operation_id::text,s.operation_id::text,r.provider_project_id,us,clock_timestamp());
 if exists(select 1 from private.r12_direct_browser_accounting where operation_id=s.operation_id) then raise exception 'r12_setup_recovery_accounting_conflict';end if;
 proof:=rel||jsonb_build_object('requestId',o.request_id,'requestHash',o.request_hash,'reservationHash',o.reservation_hash,'releaseEvidenceHash',rel_hash,'usageEvidenceHash',us_hash,'observedAt',private.r12_direct_time(clock_timestamp()));proof:=proof||jsonb_build_object('recoveryHash',private.stage14_hash(proof));
 insert into private.r12_steel_setup_recoveries values(s.operation_id,proof->>'recoveryHash',f->>'receiptHash',rel_hash,proof,clock_timestamp());
 -- Same bounded-pending record contract: no actual, refund or reservation release.
 body:=jsonb_build_object('version','r12.public-browser-accounting.1','businessId',e.business_id,'goalId',e.goal_id,'authorityRootId',e.authority_root_id,'envelopeHash',e.content_hash,'providerProjectId',r.provider_project_id,'operationKind','owner_setup','operationId',s.operation_id,'operationReceiptHash',f->>'receiptHash','requestHash',o.request_hash,'reservationId',o.request_id,'reservationHash',o.reservation_hash,'quoteHash',o.quote_hash,'routeHash',r.route_hash,'tariffHash',r.tariff_hash,'qualificationHash',r.qualification_hash,'releaseProofHash',rel_hash,'usageIdentityHash',identity_hash,'maximumMicrounits',o.maximum_microunits::text,'currency','USD','revision',1,'previousRecordHash',null,'recordedAt',private.r12_direct_time(clock_timestamp()),'status','qualified_bounded_pending','actualMicrounits',null,'providerBillingRecordHash',null);body:=body||jsonb_build_object('recordHash',private.stage14_hash(body));
 insert into private.r12_direct_browser_accounting values(s.operation_id,1,null,body->>'recordHash','qualified_bounded_pending',null,null,body,clock_timestamp());
 return private.r12_steel_setup_recovery_receipt(s.operation_id,p_payload->>'failedReceiptHash');
end $$;

-- One reviewed deployment successor for this exact failed setup and remaining
-- envelope. It creates no cash, grant, access approval or browser reservation.
create table private.r12_steel_setup_repair_releases(
 review_hash text primary key check(review_hash=private.stage14_hash(content-'reviewHash')),
 envelope_id uuid not null unique references private.r12_direct_test_envelopes(id),
 package_hash text not null unique references private.r12_direct_enrollment_packages(package_hash),
 original_operation_id uuid not null unique references private.r12_etsy_steel_setups(operation_id),
 replacement_operation_id uuid not null unique,content jsonb not null,expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp());
create table private.r12_steel_setup_repair_release_revocations(review_hash text primary key references private.r12_steel_setup_repair_releases(review_hash),created_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['r12_steel_setup_repair_releases','r12_steel_setup_repair_release_revocations'] loop
 execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);
 execute format('create trigger immutable_setup_recovery before insert or update or delete on private.%I for each row execute function private.r05_guard()',t);end loop;end $$;
create function private.r12_steel_setup_repair_release_revoke_lock() returns trigger language plpgsql set search_path='' as $$begin
 perform 1 from public.businesses b join private.r12_direct_test_envelopes e on e.business_id=b.id join private.r12_steel_setup_repair_releases r on r.envelope_id=e.id where r.review_hash=new.review_hash for update of b;return new;end $$;
create trigger r12_setup_release_revoke_lock before insert on private.r12_steel_setup_repair_release_revocations for each row execute function private.r12_steel_setup_repair_release_revoke_lock();
create function private.r12_steel_setup_repair_terms(e private.r12_direct_test_envelopes,p private.r12_direct_enrollment_packages) returns text language sql immutable set search_path='' as $$
 select private.stage14_hash(jsonb_build_object('packageHash',p.package_hash,'envelopeHash',e.content_hash,'grantReview',p.content->'grantReview','registry',p.content->'registry'))
$$;
create function private.r12_steel_setup_repair_release_current(envelope uuid) returns private.r12_steel_setup_repair_releases language plpgsql set search_path='' as $$
declare r private.r12_steel_setup_repair_releases;e private.r12_direct_test_envelopes;p private.r12_direct_enrollment_packages;begin
 select * into strict r from private.r12_steel_setup_repair_releases where envelope_id=envelope;
 select * into strict e from private.r12_direct_test_envelopes where id=envelope;
 select * into strict p from private.r12_direct_enrollment_packages where package_hash=r.package_hash;
 perform 1 from public.businesses where id=e.business_id and owner_user_id=e.owner_id for update;
 if not found or r.expires_at<=clock_timestamp() or exists(select 1 from private.r12_steel_setup_repair_release_revocations where review_hash=r.review_hash)
 or r.content->>'unchangedTermsHash' is distinct from private.r12_steel_setup_repair_terms(e,p)
 or r.content->'release'->>'databaseDefinitionHash' is distinct from private.r12_direct_enrollment_definition_hash()
 then raise exception 'r12_setup_repair_release_inactive';end if;return r;
end $$;
create function private.r12_steel_publish_repair_release(body jsonb) returns jsonb language plpgsql set search_path='' as $$
declare s private.r12_etsy_steel_setups;e private.r12_direct_test_envelopes;p private.r12_direct_enrollment_packages;old private.r12_steel_setup_repair_releases;c jsonb;old_config jsonb;rel jsonb;ev jsonb;k text;stamp timestamptz;expiry timestamptz;begin
 if current_user in ('anon','authenticated','service_role') or not pg_has_role(current_user,(select proowner from pg_proc where oid='private.r12_steel_publish_repair_release(jsonb)'::regprocedure),'USAGE') then raise exception 'r12_setup_repair_operator_required' using errcode='42501';end if;
 perform private.r12_direct_scan(body);perform private.r04_keys(body,array['version','businessId','ownerId','goalId','testEnvelopeId','testEnvelopeHash','originalOperationId','failedReceiptHash','reviewedPackageHash','originalReleaseHash','replacementOperationId','configuration','configurationHash','release','unchangedTermsHash','securityApprovalHash','reviewedAt','expiresAt','reviewHash']);
 foreach k in array array['reviewedAt','expiresAt'] loop
 if coalesce(body->>k,'')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' or private.r12_direct_time((body->>k)::timestamptz) is distinct from body->>k then raise exception 'r12_setup_repair_release_invalid';end if;end loop;
 stamp:=(body->>'reviewedAt')::timestamptz;expiry:=(body->>'expiresAt')::timestamptz;
 foreach k in array array['testEnvelopeHash','failedReceiptHash','reviewedPackageHash','originalReleaseHash','configurationHash','unchangedTermsHash','securityApprovalHash','reviewHash'] loop if coalesce(body->>k,'')!~'^[a-f0-9]{64}$' then raise exception 'r12_setup_repair_release_invalid';end if;end loop;
 select * into strict s from private.r12_etsy_steel_setups where operation_id=(body->>'originalOperationId')::uuid;
 select * into strict e from private.r12_direct_test_envelopes where id=s.envelope_id;
 select p0.* into strict p from private.r12_direct_test_confirmations tc join private.r12_direct_enrollment_grants g on g.grant_id=tc.grant_id join private.r12_direct_enrollment_packages p0 on p0.package_hash=g.package_hash where tc.envelope_id=e.id;
 perform 1 from public.businesses where id=e.business_id and owner_user_id=e.owner_id for update;if not found then raise exception 'r12_setup_repair_owner_required';end if;
 select * into old from private.r12_steel_setup_repair_releases where envelope_id=e.id;
 if old.review_hash is not null then if old.content is distinct from body then raise exception 'r12_setup_repair_release_conflict';end if;return jsonb_build_object('reviewHash',old.review_hash,'authorityCreated',false);end if;
 select a.content->'configuration' into strict old_config from private.r12_steel_create_config_uses u join private.r12_steel_create_config_permits t on t.admission_hash=u.admission_hash join private.r12_steel_config_attestations a on a.attestation_hash=t.attestation_hash where u.operation_id=s.operation_id;
 c:=body->'configuration';rel:=body->'release';perform private.r04_keys(c,array['version','provider','baseUrl','region','providerProjectId','environment','deploymentId','releaseCommitSha']);
 if body->>'version' is distinct from 'r12.steel-setup-repair-release.1' or body->>'reviewHash' is distinct from private.stage14_hash(body-'reviewHash')
 or body->>'businessId' is distinct from e.business_id::text or body->>'ownerId' is distinct from e.owner_id::text or body->>'goalId' is distinct from e.goal_id::text
 or body->>'testEnvelopeId' is distinct from e.id::text or body->>'testEnvelopeHash' is distinct from e.content_hash or body->>'reviewedPackageHash' is distinct from p.package_hash
 or body->>'originalReleaseHash' is distinct from private.stage14_hash(p.review_evidence->'release') or body->>'unchangedTermsHash' is distinct from private.r12_steel_setup_repair_terms(e,p)
 or (body->>'replacementOperationId')::uuid is null or body->>'replacementOperationId'=s.operation_id::text or exists(select 1 from private.r12_etsy_steel_setups where operation_id=(body->>'replacementOperationId')::uuid)
 or stamp>clock_timestamp() or expiry<=clock_timestamp() or expiry>least(e.expires_at,p.expires_at,stamp+interval '24 hours')
 or c->>'version' is distinct from 'r12.steel-runtime-configuration.1' or c->>'provider' is distinct from 'steel' or c->>'baseUrl' is distinct from 'https://api.steel.dev' or c->>'environment' is distinct from 'production'
 or c->>'providerProjectId' is distinct from s.scope->>'providerProjectId' or c->>'releaseCommitSha' is distinct from rel->>'commitSha'
 or coalesce(c->>'deploymentId','')!~'^dpl_[A-Za-z0-9_-]{1,124}$' or (c->'region' is distinct from 'null'::jsonb and coalesce(c->>'region','')!~'^[A-Za-z0-9_-]{1,64}$')
 or (c-'deploymentId'-'releaseCommitSha') is distinct from (old_config-'deploymentId'-'releaseCommitSha')
 or body->>'configurationHash' is distinct from private.stage14_hash(c) then raise exception 'r12_setup_repair_release_invalid';end if;
 perform private.r12_steel_setup_recovery_context(s.operation_id,body->>'failedReceiptHash');
 -- Validate the new exact release with the established independent review
 -- rules, keeping every source/model/data/privacy/pack term unchanged.
 ev:=jsonb_set(p.review_evidence,'{release}',rel);
 perform private.r12_direct_enrollment_evidence(jsonb_set(p.content,'{reviewEvidenceHash}',to_jsonb(private.stage14_hash(ev))),ev);
 insert into private.r12_steel_setup_repair_releases values(body->>'reviewHash',e.id,p.package_hash,s.operation_id,(body->>'replacementOperationId')::uuid,body,expiry,clock_timestamp());
 perform private.r12_direct_test_current(e.id);
 return jsonb_build_object('reviewHash',body->>'reviewHash','authorityCreated',false);
end $$;
-- Current ancestry authenticates the reviewed successor release without ever
-- changing the old package, review, profile or registry rows.
create function private.r12_steel_setup_repair_ancestor(p private.r12_direct_enrollment_packages) returns void language plpgsql set search_path='' as $$
declare r private.r12_steel_setup_repair_releases;ev jsonb;begin
 select * into r from private.r12_steel_setup_repair_releases where package_hash=p.package_hash;
 if r.review_hash is null then perform private.r12_direct_enrollment_evidence(p.content,p.review_evidence);return;end if;
 r:=private.r12_steel_setup_repair_release_current(r.envelope_id);ev:=jsonb_set(p.review_evidence,'{release}',r.content->'release');
 perform private.r12_direct_enrollment_evidence(jsonb_set(p.content,'{reviewEvidenceHash}',to_jsonb(private.stage14_hash(ev))),ev);
end $$;
do $$declare d text;old text:='perform private.r12_direct_enrollment_evidence(p.content,p.review_evidence);';begin
 d:=pg_get_functiondef('private.r12_direct_enrollment_ancestor(text)'::regprocedure);
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_ancestor_drift';end if;
 execute replace(d,old,'perform private.r12_steel_setup_repair_ancestor(p);');end $$;
create function private.r12_steel_setup_repair_attestation(body jsonb) returns boolean language plpgsql set search_path='' as $$
declare r private.r12_steel_setup_repair_releases;begin
 select x.* into r from private.r12_steel_setup_repair_releases x join private.r12_etsy_steel_setups s on s.operation_id=x.original_operation_id where s.route_hash=body->>'routeHash' and x.content->>'configurationHash'=body->>'configurationHash';
 if r.review_hash is null then return false;end if;r:=private.r12_steel_setup_repair_release_current(r.envelope_id);
 return body->'configuration'=r.content->'configuration' and body->>'deploymentEvidenceHash'=r.content->'release'->>'deploymentReceiptHash';
end $$;
-- The new HMAC is authenticated by a fresh independently known-session GET and
-- the same private publisher; a release review alone never invents its value.
do $$declare d text;old text:='body->>''credentialBindingHash'' is distinct from r.credential_binding_hash';begin
 d:=pg_get_functiondef('private.r12_steel_config_attestation_check(jsonb)'::regprocedure);
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_attestation_drift';end if;
 execute replace(d,old,'(body->>''credentialBindingHash'' is distinct from r.credential_binding_hash and not private.r12_steel_setup_repair_attestation(body))');end $$;
create function private.r12_steel_setup_repair_create_release(envelope uuid,operation uuid,attestation jsonb) returns void language plpgsql set search_path='' as $$
declare r private.r12_steel_setup_repair_releases;d private.r12_steel_setup_repair_debits;a private.r12_direct_phase_attempts;begin
 select * into r from private.r12_steel_setup_repair_releases where envelope_id=envelope;
 if r.review_hash is null then perform private.r12_steel_config_release_check(envelope,attestation);return;end if;
 r:=private.r12_steel_setup_repair_release_current(envelope);select * into d from private.r12_steel_setup_repair_debits where envelope_id=envelope;
 if d.content->>'releaseSuccessorHash' is distinct from r.review_hash or d.replacement_operation_id is distinct from r.replacement_operation_id
 or attestation->'configuration' is distinct from r.content->'configuration' or attestation->>'configurationHash' is distinct from r.content->>'configurationHash'
 or attestation->>'deploymentEvidenceHash' is distinct from r.content->'release'->>'deploymentReceiptHash'
 then raise exception 'r12_setup_repair_exact_release_required';end if;
 if operation=r.replacement_operation_id then return;end if;
 if exists(select 1 from private.r12_etsy_steel_verification_runs where operation_id=operation and setup_operation_id=r.replacement_operation_id) then return;end if;
 select * into a from private.r12_direct_phase_attempts where phase='source' and source_scope->>'operationId'=operation::text;
 if a.attempt_id is not null and exists(select 1 from private.r12_etsy_steel_candidates c join private.r12_direct_research_setups s on s.scope_id=a.scope_id
 where c.operation_id=r.replacement_operation_id and c.binding_id=(a.source_scope->'accountBinding'->>'profileBindingId')::uuid and c.binding_revision=(a.source_scope->'accountBinding'->>'profileBindingRevision')::uuid and s.envelope_id=envelope) then return;end if;
 raise exception 'r12_setup_repair_operation_lineage_required';
end $$;
do $$declare d text;old text;begin
 d:=pg_get_functiondef('private.r12_steel_create_config_context(uuid,text)'::regprocedure);old:='expires:=least(expires,(renderer->>''expiresAt'')::timestamptz);';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_context_expiry_drift';end if;execute replace(d,old,old||' expires:=least(expires,(select expires_at from private.r12_steel_setup_repair_releases where envelope_id=e.id));');
 d:=pg_get_functiondef('public.r12_steel_create_config_admit(uuid,jsonb,text)'::regprocedure);old:='perform private.r12_steel_config_release_check((ctx->>''envelopeId'')::uuid,att.content);';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_admit_drift';end if;execute replace(d,old,'perform private.r12_steel_setup_repair_create_release((ctx->>''envelopeId'')::uuid,op,att.content);');
 d:=pg_get_functiondef('private.r12_steel_create_config_consume()'::regprocedure);old:='perform private.r12_steel_config_release_check((ctx->>''envelopeId'')::uuid,a.content);';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_consume_drift';end if;execute replace(d,old,'perform private.r12_steel_setup_repair_create_release((ctx->>''envelopeId'')::uuid,op,a.content);');
 -- Key validation is repeated after the shared revocation lock; a stale
 -- pre-wait snapshot can never authorize late billing evidence.
 d:=pg_get_functiondef('public.r12_direct_browser_ledger(uuid,uuid,text,jsonb,text)'::regprocedure);old:='perform 1 from public.businesses where id=e.business_id for update;';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_recovery_ledger_lock_drift';end if;
 execute replace(d,old,old||' if k.valid_until<=clock_timestamp() or exists(select 1 from private.r12_direct_browser_evidence_key_revocations where key_hash=k.key_hash) then raise exception ''r12_direct_evidence_key_required'' using errcode=''42501'';end if;');
end $$;

create function private.r12_steel_setup_replacement_view(operation uuid,proposal uuid default null) returns jsonb language plpgsql stable set search_path='' as $$
declare p private.r12_steel_setup_replacement_proposals;r private.r12_steel_setup_recoveries;begin
 select * into r from private.r12_steel_setup_recoveries where operation_id=operation;
 select x.* into p from private.r12_steel_setup_replacement_proposals x left join private.r12_steel_setup_repair_debits d on d.proposal_id=x.id where x.operation_id=operation and (proposal is null or x.id=proposal) order by (d.proposal_id is not null) desc,x.created_at desc,x.id desc limit 1;
 return jsonb_build_object('version','etsy.steel-setup-replacement-view.1','operationId',operation,'recovery',case when r.operation_id is null then null else private.r12_steel_setup_recovery_receipt(operation,r.failed_receipt_hash) end,'proposal',p.content,'confirmed',exists(select 1 from private.r12_steel_setup_repair_debits where proposal_id=p.id));
end $$;
create function public.r12_owner_steel_replacement(p_business_id uuid,p_operation text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare s private.r12_etsy_steel_setups;e private.r12_direct_test_envelopes;r private.r12_steel_setup_recoveries;p private.r12_steel_setup_replacement_proposals;d private.r12_steel_setup_repair_debits;rr private.r12_steel_setup_repair_releases;body jsonb;h text;ceiling integer;begin
 perform private.r05_owner(p_business_id);perform private.r04_safe(p_payload);
 if p_operation='confirm' then perform private.r04_keys(p_payload,array['proposalId','proposalHash','submissionId']);
 select * into p from private.r12_steel_setup_replacement_proposals where id=(p_payload->>'proposalId')::uuid and proposal_hash=p_payload->>'proposalHash' and owner_id=auth.uid();
 select * into s from private.r12_etsy_steel_setups where operation_id=p.operation_id and business_id=p_business_id and owner_id=auth.uid();
 else
 perform private.r04_keys(p_payload,case when p_operation='read' then array['operationId'] else array['operationId','recoveryHash','submissionId'] end);
 select * into s from private.r12_etsy_steel_setups where operation_id=(p_payload->>'operationId')::uuid and business_id=p_business_id and owner_id=auth.uid();end if;
 if s.operation_id is null then raise exception 'r12_setup_replacement_owner_required' using errcode='42501';end if;
 perform 1 from public.businesses where id=p_business_id and owner_user_id=auth.uid() for update;if not found then raise exception 'r12_setup_replacement_owner_required' using errcode='42501';end if;
 if p_operation='read' then return private.r12_steel_setup_replacement_view(s.operation_id);end if;
 if coalesce(p_operation,'') not in ('prepare','confirm') or (p_payload->>'submissionId')::uuid is null then raise exception 'r12_setup_replacement_operation';end if;
 select * into strict e from private.r12_direct_test_envelopes where id=s.envelope_id;
 select * into r from private.r12_steel_setup_recoveries where operation_id=s.operation_id;
 select * into d from private.r12_steel_setup_repair_debits where envelope_id=e.id;
 if p_operation='confirm' and d.proposal_id=p.id then return private.r12_steel_setup_replacement_view(s.operation_id);end if;
 if d.envelope_id is not null then raise exception 'r12_setup_replacement_already_used';end if;
 if r.operation_id is null or (p_operation='prepare' and r.recovery_hash is distinct from p_payload->>'recoveryHash') then raise exception 'r12_setup_replacement_recovery_required';end if;
 perform private.r12_steel_setup_recovery_context(s.operation_id,r.failed_receipt_hash);
 rr:=private.r12_steel_setup_repair_release_current(e.id);perform private.r12_direct_test_current(e.id);perform private.r12_direct_financial_check(e.id,(s.scope->>'maximumBrowserMicrounits')::bigint+(s.scope->>'verificationMaximumMicrounits')::bigint);
 if (e.content->>'maximumAttemptsInWindow')::integer<2 or exists(select 1 from private.r12_direct_research_setups where envelope_id=e.id)
 or (select count(*) from private.r12_direct_browser_operations where envelope_id=e.id)<>1
 or private.r12_steel_setup_recovery_receipt(s.operation_id,r.failed_receipt_hash)->>'status' not in ('qualified_bounded_pending','final_actual') then raise exception 'r12_setup_replacement_unused_test_required';end if;
 select least(64,cumulative_dispatches_ceiling) into strict ceiling from private.r12_direct_grant_reviews where grant_id=(e.content->>'grantId')::uuid;
 if (e.content->'origin'->'predecessor'->'closure'->>'baseDispatches')::integer+3>ceiling then raise exception 'r12_setup_replacement_dispatch_limit';end if;
 if p_operation='prepare' then
 h:=private.stage14_hash(p_payload);select * into p from private.r12_steel_setup_replacement_proposals where owner_id=auth.uid() and submission_id=(p_payload->>'submissionId')::uuid;
 if p.id is not null then if p.request_hash<>h or p.operation_id<>s.operation_id then raise exception 'r12_setup_replacement_idempotency_conflict';end if;return private.r12_steel_setup_replacement_view(s.operation_id,p.id);end if;
 p.id:=gen_random_uuid();p.replacement_operation_id:=rr.replacement_operation_id;p.expires_at:=least(e.expires_at,clock_timestamp()+interval '5 minutes');
 body:=jsonb_build_object('version','etsy.steel-setup-replacement-proposal.1','proposalId',p.id,'businessId',s.business_id,'goalId',e.goal_id,'authorityRootId',e.authority_root_id,'testEnvelopeId',e.id,'testEnvelopeHash',e.content_hash,'originalOperationId',s.operation_id,'originalScopeHash',s.scope_hash,'failedReceiptHash',r.failed_receipt_hash,'recoveryHash',r.recovery_hash,'replacementOperationId',p.replacement_operation_id,'accountId',s.account_id,'providerProjectId',s.scope->>'providerProjectId','routeHash',s.route_hash,'maximumBrowserMicrounits',s.scope->>'maximumBrowserMicrounits','originalHeldMaximumMicrounits',s.scope->>'maximumBrowserMicrounits','releaseSuccessorHash',rr.review_hash,'releaseCommitSha',rr.content->'release'->>'commitSha','deploymentId',rr.content->'configuration'->>'deploymentId','maximumTestMicrounits',e.maximum_microunits::text,'originalMaximumUnits',e.content->'maximumAttemptsInWindow','setupRepairUnits',1,'remainingResearchUnits',(e.content->>'maximumAttemptsInWindow')::integer-1,'cumulativeDispatchesCeiling',ceiling,'expiresAt',private.r12_direct_time(p.expires_at));body:=body||jsonb_build_object('proposalHash',private.stage14_hash(body));
 insert into private.r12_steel_setup_replacement_proposals values(p.id,s.operation_id,e.id,auth.uid(),(p_payload->>'submissionId')::uuid,h,p.replacement_operation_id,body,body->>'proposalHash',p.expires_at,clock_timestamp());
 else
 if p.expires_at<=clock_timestamp() or p.content->>'releaseSuccessorHash' is distinct from rr.review_hash or p.content->>'recoveryHash'<>r.recovery_hash then raise exception 'r12_setup_replacement_proposal_expired';end if;
 body:=jsonb_build_object('version','etsy.steel-setup-repair-debit.1','proposalId',p.id,'proposalHash',p.proposal_hash,'testEnvelopeId',e.id,'testEnvelopeHash',e.content_hash,'originalOperationId',s.operation_id,'replacementOperationId',p.replacement_operation_id,'ownerId',auth.uid(),'recoveryHash',r.recovery_hash,'originalMaximumUnits',e.content->'maximumAttemptsInWindow','setupRepairUnits',1,'remainingResearchUnits',(e.content->>'maximumAttemptsInWindow')::integer-1,'releaseSuccessorHash',rr.review_hash,'reason','owner_confirmed_technical_setup_repair','confirmedAt',private.r12_direct_time(clock_timestamp()));body:=body||jsonb_build_object('debitHash',private.stage14_hash(body));
 insert into private.r12_steel_setup_repair_debits values(e.id,p.id,s.operation_id,p.replacement_operation_id,auth.uid(),body,body->>'debitHash',clock_timestamp());end if;
 return private.r12_steel_setup_replacement_view(s.operation_id,p.id);
end $$;

create function private.r12_steel_setup_replacement_guard() returns trigger language plpgsql set search_path='' as $$
declare d private.r12_steel_setup_repair_debits;s private.r12_etsy_steel_setups;rr private.r12_steel_setup_repair_releases;field text;begin
 perform 1 from public.businesses where id=new.business_id for update;
 if not exists(select 1 from private.r12_direct_browser_operations o join private.r05_reservations v on v.request_id=o.request_id where o.envelope_id=new.envelope_id and o.scope->>'version'='etsy.steel-owner-handoff-scope.1') then return new;end if;
 select * into d from private.r12_steel_setup_repair_debits where envelope_id=new.envelope_id and replacement_operation_id=new.operation_id and owner_id=new.owner_id;
 select * into s from private.r12_etsy_steel_setups where operation_id=d.original_operation_id;
 if d.envelope_id is null or s.operation_id is null or new.account_id<>s.account_id or new.route_hash<>s.route_hash
 or new.approval_id=s.approval_id or new.approval_revision=s.approval_revision or new.account_revision=s.account_revision or new.profile_expires_at>s.profile_expires_at
 or exists(select 1 from private.r12_etsy_steel_setups where operation_id=d.replacement_operation_id)
 then raise exception 'r12_setup_exact_replacement_required';end if;
 rr:=private.r12_steel_setup_repair_release_current(new.envelope_id);if d.content->>'releaseSuccessorHash' is distinct from rr.review_hash or rr.replacement_operation_id<>new.operation_id then raise exception 'r12_setup_repair_exact_release_required';end if;
 foreach field in array array['businessId','ownerId','goalId','authorityRootId','testEnvelopeId','testEnvelopeHash','providerProjectId','routeHash','maximumSessionMs','maximumBrowserMicrounits','verificationMaximumMicrounits','expectedShopName','expectedShopId','quoteHash','verificationQuoteHash','purpose'] loop
 if new.scope->field is distinct from s.scope->field then raise exception 'r12_setup_replacement_scope_changed';end if;end loop;
 return new;
end $$;
create trigger r12_steel_setup_replacement before insert on private.r12_etsy_steel_setups for each row execute function private.r12_steel_setup_replacement_guard();

-- Reservation and marker retain every original total/financial limit. Only the
-- exact confirmed successor may be the second login; a third remains denied.
do $$ declare d text;old text:='if prior>0 then raise exception ''r12_direct_setup_session_limit'';end if;';replacement text;begin
 d:=pg_get_functiondef('private.r12_direct_setup_operation_guard()'::regprocedure);
 replacement:=$r$if prior>0 and not (prior=1 and o.scope->>'version'='etsy.steel-owner-handoff-scope.1' and exists(
 select 1 from private.r12_steel_setup_repair_debits d join private.r12_steel_setup_recoveries z on z.operation_id=d.original_operation_id
 where d.envelope_id=e.id and d.replacement_operation_id=o.id and not exists(select 1 from private.r12_direct_browser_anomalies where operation_id=d.original_operation_id))) then raise exception 'r12_direct_setup_session_limit';end if;$r$;
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_replacement_guard_drift';end if;execute replace(d,old,replacement);
end $$;

create function private.r12_direct_research_unit_limit(envelope uuid) returns integer language sql stable set search_path='' as $$
 select (e.content->>'maximumAttemptsInWindow')::integer-case when d.envelope_id is null then 0 else 1 end from private.r12_direct_test_envelopes e left join private.r12_steel_setup_repair_debits d on d.envelope_id=e.id where e.id=envelope
$$;
-- Every fresh scope, quote and renewal sees the same reduced research ceiling.
-- Original envelope and all saved historical scopes/quotes are untouched.
do $$ declare sig text;d text;old text;replacement text;begin
 foreach sig in array array['private.r12_direct_prepare_research(uuid,jsonb,text)','private.r12_direct_prepare_research_v2(uuid,jsonb,text)'] loop
 d:=pg_get_functiondef(sig::regprocedure);old:='n:=(e.content->>''maximumAttemptsInWindow'')::integer;';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_prepare_drift: %',sig;end if;execute replace(d,old,'n:=private.r12_direct_research_unit_limit(e.id);');end loop;
 foreach sig in array array['private.r12_direct_profile(private.r12_direct_test_envelopes,jsonb,timestamp with time zone)','private.r12_direct_browser_quote_context(private.r12_direct_test_envelopes,jsonb)'] loop
 d:=pg_get_functiondef(sig::regprocedure);old:='''maximumAttemptsInWindow'',e.content->''maximumAttemptsInWindow''';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_projection_drift: %',sig;end if;execute replace(d,old,'''maximumAttemptsInWindow'',to_jsonb(private.r12_direct_research_unit_limit(e.id))');end loop;
 foreach sig in array array['private.r12_direct_research_quote_before_sonnet(private.r12_direct_test_envelopes,jsonb,jsonb)','private.r12_direct_research_quote_sonnet(private.r12_direct_test_envelopes,jsonb,jsonb)'] loop
 d:=pg_get_functiondef(sig::regprocedure);old:='q->''maximumAttemptsInWindow'' is distinct from e.content->''maximumAttemptsInWindow''';
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_quote_drift: %',sig;end if;execute replace(d,old,'q->''maximumAttemptsInWindow'' is distinct from to_jsonb(private.r12_direct_research_unit_limit(e.id))');end loop;
 d:=pg_get_functiondef('private.r12_direct_owner_quote_context(uuid,jsonb,text)'::regprocedure);old:='return body||jsonb_build_object(''contextHash'',private.stage14_hash(body));';
 replacement:=$r$if exists(select 1 from private.r12_steel_setup_repair_debits where envelope_id=e.id) then
 body:=body||jsonb_build_object('version','r12.direct-owner-research-quote-context.3','originalMaximumAttemptsInWindow',e.content->'maximumAttemptsInWindow','setupRepairUnits',1,'setupRepairDebitHash',(select debit_hash from private.r12_steel_setup_repair_debits where envelope_id=e.id));end if;
 return body||jsonb_build_object('contextHash',private.stage14_hash(body));$r$;
 if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_repair_context_drift';end if;execute replace(d,old,replacement);
end $$;

-- Late genuine USD billing can reconcile this specifically authenticated remote
-- terminal proof, without turning it into a local-disposal acknowledgement.
create function private.r12_steel_no_handoff_release(operation uuid,evidence text) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.r12_steel_setup_recoveries p join private.r12_direct_browser_evidence x on x.evidence_hash=p.release_evidence_hash and x.operation_id=p.operation_id where p.operation_id=operation and x.evidence_hash=evidence and x.content->>'version'='etsy.steel-provider-terminal-no-handoff.1' and x.content->'ownerHandoffIssued'='false'::jsonb and x.content->>'localObserverDisposal'='unattested')
$$;
do $$ declare d text;old text;begin
 d:=pg_get_functiondef('private.r12_direct_browser_reconcile(uuid,text,text,text)'::regprocedure);
 old:='rel.content->''observersDisposed'' is distinct from ''true''::jsonb';if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_recovery_reconcile_drift';end if;
 d:=replace(d,old,'(rel.content->''observersDisposed'' is distinct from ''true''::jsonb and not private.r12_steel_no_handoff_release(o.id,rel.evidence_hash))');
 old:='coalesce(rel.content->>''disposalProofHash'','''')!~''^[a-f0-9]{64}$''';if (length(d)-length(replace(d,old,'')))/length(old)<>1 then raise exception 'r12_setup_recovery_reconcile_hash_drift';end if;
 execute replace(d,old,'(coalesce(rel.content->>''disposalProofHash'','''')!~''^[a-f0-9]{64}$'' and not private.r12_steel_no_handoff_release(o.id,rel.evidence_hash))');
end $$;

do $$ declare f record;begin for f in select p.oid::regprocedure name from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and (p.proname like 'r12_steel_setup_%' or p.proname in ('r12_direct_research_unit_limit','r12_steel_no_handoff_release','r12_steel_publish_repair_release')) loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.name);end loop;end $$;
revoke all on function public.r12_etsy_steel_recovery_server(uuid,text,jsonb,text) from public,anon,authenticated,service_role;
grant execute on function public.r12_etsy_steel_recovery_server(uuid,text,jsonb,text) to anon;
revoke all on function public.r12_owner_steel_replacement(uuid,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.r12_owner_steel_replacement(uuid,text,jsonb) to authenticated;
commit;
